describe('Hellfire Arrow mob skill',function()
 it('uses its Fire magical plan and applies random Burn only after processing',function()
  local arrow=require('scripts/actions/mobskills/hellfire_arrow');local move,process,effect,random=xi.mobskills.mobMagicalMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove,math.random;local params,damage,burn=nil,nil,nil;local mob={getMainLvl=function()return 75 end};local target={takeDamage=function(_,...)damage={...}end};xi.mobskills.mobMagicalMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.MAGICAL,damageType=xi.damageType.FIRE}end;xi.mobskills.processDamage=function()return false end;xi.mobskills.mobStatusEffectMove=function(_,_,...)burn={...}end;math.random=function(min,max)assert(min==10 and max==30);return 20 end
  assert(arrow.onMobSkillCheck(target,mob,{})==0 and arrow.onMobWeaponSkill(mob,target,{},{})==123);assert(params.baseDamage==77 and params.fTP[1]==2.7 and params.fTP[2]==2.7 and params.fTP[3]==2.7 and params.element==xi.element.FIRE and params.attackType==xi.attackType.MAGICAL and params.damageType==xi.damageType.FIRE and params.shadowBehavior==xi.mobskills.shadowBehavior.WIPE_SHADOWS and damage==nil and burn==nil);xi.mobskills.processDamage=function()return true end;arrow.onMobWeaponSkill(mob,target,{},{})
  xi.mobskills.mobMagicalMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove,math.random=move,process,effect,random;assert(damage[1]==123 and damage[2]==mob and damage[3]==xi.attackType.MAGICAL and damage[4]==xi.damageType.FIRE);assert(burn[1]==xi.effect.BURN and burn[2]==20 and burn[3]==3 and burn[4]==60)
 end)
end)
